contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(_l1FeeScalar <= type(uint256).max);

        uint64 numberBefore = c.number(); if (__ESBMC_reverted()) return;
        uint64 timestampBefore = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 basefeeBefore = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 hashBefore = c.hash(); if (__ESBMC_reverted()) return;
        uint64 sequenceNumberBefore = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 batcherHashBefore = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 l1FeeOverheadBefore = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 l1FeeScalarBefore = c.l1FeeScalar(); if (__ESBMC_reverted()) return;

        bool completed = false;
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            completed = false;
        } else {
            completed = true;
        }

        bool unchanged =
            c.number() == numberBefore &&
            c.timestamp() == timestampBefore &&
            c.basefee() == basefeeBefore &&
            c.hash() == hashBefore &&
            c.sequenceNumber() == sequenceNumberBefore &&
            c.batcherHash() == batcherHashBefore &&
            c.l1FeeOverhead() == l1FeeOverheadBefore &&
            c.l1FeeScalar() == l1FeeScalarBefore;

        assert(completed == false && unchanged);
    }

    receive() external payable {}
}

